select pg_temp.assert_true(to_regprocedure('public.finish_performance_review_mail(uuid,uuid,text,text)') is not null,'finish RPC exists');
set local role authenticated;
select pg_temp.expect_state('select public.finish_performance_review_mail(null,null,null,null)','42501');
reset role;
set local role anon;
select pg_temp.expect_state('select public.finish_performance_review_mail(null,null,null,null)','42501');
reset role;
set local role service_role;
select pg_temp.assert_true(public.finish_performance_review_mail(null,null,'unknown',repeat('a',64)) is false,'null finish cannot reconcile');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,gen_random_uuid(),'provider_accepted',repeat('a',64)) is false,'wrong token cannot reconcile');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'provider_accepted',repeat('b',64)) is false,'wrong attachment cannot reconcile');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'queued',repeat('a',64)) is false,'outcome vocabulary closed');
savepoint accepted;
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'provider_accepted',repeat('a',64)) is true,'real sending acceptance recorded');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'provider_accepted',repeat('a',64)) is true,'same accepted ack idempotent');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'unknown',repeat('a',64)) is false,'accepted cannot downgrade to unknown');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'rejected',repeat('a',64)) is false,'accepted cannot downgrade to rejection');
reset role;
select pg_temp.assert_true((select state='provider_accepted' and outcome='provider_accepted' from private.performance_review_mail_outbox),'accepted state preserved');
rollback to accepted;
set local role service_role;
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'unknown',repeat('a',64)) is true,'sending unknown enters sticky hold');
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'unknown',repeat('a',64)) is true,'same unknown ack idempotent');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,repeat('a',64)) is false,'hold cannot authorize another send');
select pg_temp.assert_true((select count(*)=0 from public.claim_performance_review_mail()),'hold cannot be reclaimed');
reset role;
select pg_temp.assert_true((select state='needs_review' and outcome='unknown' from private.performance_review_mail_outbox),'unknown is durable needs_review');
set local role service_role;
select pg_temp.assert_true(public.finish_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,'provider_accepted',repeat('a',64)) is true,'bound real delayed ack may reconcile sending unknown');
select pg_temp.assert_true(public.begin_performance_review_mail((current_setting('test.claim')::jsonb->>'delivery_id')::uuid,(current_setting('test.claim')::jsonb->>'claim_token')::uuid,repeat('a',64)) is false,'reconciliation never creates resend permission');
reset role;
select pg_temp.assert_true(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and (p.proname like '%performance_review%') and has_function_privilege('service_role',p.oid,'EXECUTE') and p.proname not in ('claim_performance_review_mail','begin_performance_review_mail','finish_performance_review_mail')),'service default grants never inherit user mutators or private helpers');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select pg_temp.assert_true(public.performance_review_workspace()->'reviews'->0=current_setting('test.submitted')::jsonb->'review','every outcome leaves employee DTO unchanged');
reset role;
